// Avisa solo cuando el estado cambia (caído ↔ recuperado), no en cada revisión
const respuesta = $input.first().json;
const url = $('Configuración').first().json.url;

const caido = Boolean(respuesta.error) || !respuesta.statusCode || respuesta.statusCode >= 400;
const detalle = respuesta.error
  ? (respuesta.error.message || String(respuesta.error))
  : 'HTTP ' + respuesta.statusCode;

// La memoria del flujo solo se guarda en ejecuciones de producción (flujo activo)
const memoria = $getWorkflowStaticData('global');
const estabaCaido = memoria.caido === true;
if (caido === estabaCaido) return [];

memoria.caido = caido;
const ahora = $now.toFormat('yyyy-MM-dd HH:mm');
let mensaje;
if (caido) {
  memoria.desde = ahora;
  mensaje = '🔴 ' + url + ' no responde (' + detalle + '). Detectado: ' + ahora + '.';
} else {
  mensaje = '🟢 ' + url + ' volvió a responder (' + detalle + '). Estuvo caído desde ' + (memoria.desde || 'hace un momento') + '.';
  delete memoria.desde;
}
return [{ json: { mensaje, caido } }];
